(function(){'use strict';
const S=window.YardSim,$=id=>document.getElementById(id),money=n=>Math.round(n).toLocaleString('ja-JP'),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const SAVE='railworks-yard-save-v1',PREFS='railworks-yard-prefs-v1';let state=S.create(),running=false,rate=1,accumulator=0,last=performance.now(),lastUI=0,selected=null,modalPanel=null,resumeAfter=false,buildResume=false,pendingPlace=null,toastTimer=0,holdUI=false,loaded=false,lastDelivery=0,lastAutosave=0,failedShown=false,inspector=null,planGeneration=0,victoryQueued=false;
let prefs={music:true,fx:true,motion:true};try{prefs={...prefs,...JSON.parse(localStorage.getItem(PREFS)||'{}')};const raw=localStorage.getItem(SAVE);if(raw){state=S.restore(raw);loaded=true;}}catch(_){/* A corrupt local save never blocks a new game. */}
const audio=new FactoryAudio();audio.setLevel('music',.22);audio.setLevel('fx',.35);audio.setChannel('music',prefs.music);audio.setChannel('fx',prefs.fx);audio.setStage(S.SCENARIOS[state.scenario].seed);lastDelivery=state.metrics.delivered;
const world=new YardWorld($('world'),$('minimap'),()=>state,selectBuilding,placeAt);world.reduced=!prefs.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;
const modal=$('modal');
function toast(message,bad=false){$('toast').textContent=message;$('toast').classList.toggle('bad',bad);$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4300);}
function result(r){toast(r.message,!r.ok);if(r.ok){audio.effect('support');save(false);}render(true);return r.ok;}
function setRunning(value){running=!!value&&!state.failed;accumulator=0;last=performance.now();audio.setPlaying(running);if(running)audio.unlock();render(true);}
function save(show=true){try{localStorage.setItem(SAVE,S.serialize(state));localStorage.setItem(PREFS,JSON.stringify(prefs));if(show)toast('このブラウザに保存しました。');return true;}catch(_){if(show)toast('保存できませんでした。ブラウザの保存容量をご確認ください。',true);return false;}}
function deadline(n){const v=Math.ceil(n);return `<span class="deadline ${v<=5?'urgent':''}">${v>=0?'納期まで あと'+v+'秒':'納期を'+Math.abs(v)+'秒超過'}</span>`;}
function train(id){const i=S.PRODUCT_IDS.indexOf(id);return `<span class="train-thumb" style="display:block;background-image:url(assets/trains-v08.png);background-size:400% 200%;background-position:${i%4*100/3}% ${Math.floor(i/4)*100}%;background-repeat:no-repeat" aria-hidden="true"></span>`;}
function preview(type){const i=S.TYPES[type].sprite;return `<span class="building-preview" style="display:block;background-image:url(assets/factory-buildings.png);background-size:300% 200%;background-position:${i%3*50}% ${Math.floor(i/3)*100}%;background-repeat:no-repeat" aria-hidden="true"></span>`;}
function render(force=false){
 if(holdUI&&!force)return;const m=S.mission(state),q=S.summary(state),day=Math.floor(state.t/120)+1,minutes=Math.floor(state.t%120*5)+480;
 $('cash').innerHTML=money(state.cash)+' <small>G</small>';$('cash').style.color=state.cash<3000?'#ffb6a1':'';$('delivered').innerHTML=state.metrics.delivered+' <small>両</small>';
 $('game-date').textContent=`DAY ${String(day).padStart(2,'0')} · ${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`;
 $('run-state').textContent=state.failed?'資金が尽きました':running?'操業中 · '+rate+'倍速':world.placement?'建設中':'一時停止中';$('play').textContent=running?'Ⅱ 停止':loaded?'▶ 再開':'▶ 操業開始';$('play').disabled=state.failed||!!world.placement||modal.open;
 document.querySelectorAll('[data-speed]').forEach(el=>el.classList.toggle('active',+el.dataset.speed===rate));$('zoom-level').textContent=Math.round(world.camera.z*100)+'%';
 $('chapter').textContent=state.scenario==='coast'?'CHAPTER '+String(state.chapter+1).padStart(2,'0'):state.scenario==='sandbox'?'FREE PLAY':'CHALLENGE';$('mission-title').textContent=m.complete?'シナリオクリア！':m.title;
 $('goal-badge').textContent=m.ready?'達成！':m.complete?'✓':'';
 $('mission-goals').innerHTML=m.goals.map(g=>`<div class="goal"><div class="goal-line"><span>${esc(g.label)}</span><b>${money(Math.max(0,g.value))} / ${money(g.target)} ${esc(g.unit)}</b></div><div class="track"><i style="width:${Math.min(100,Math.max(0,g.value/g.target*100))}%"></i></div></div>`).join('');
 $('mission-action').textContent=m.ready?'目標達成！ 報酬を受け取る':m.complete?'次のシナリオへ':'工場長のヒント';
 const important=state.buildings.filter(b=>b.broken||S.status(state,b).kind==='blocked');$('event-count').textContent=important.length?'! '+important.length:'';
 $('event-list').innerHTML=state.news.slice(0,4).map(n=>`<div class="event ${esc(n.kind)}"><button ${n.buildingId?'data-select="'+esc(n.buildingId)+'"':'data-panel="events"'}><strong>${esc(n.title)}</strong><small>${esc(n.body)}</small></button></div>`).join('');
 $('order-badge').textContent=state.offers.length;
 if(selected&&!modal.open&&!document.activeElement?.closest('#context-panel'))renderBuilding();
 if(state.metrics.delivered>lastDelivery){lastDelivery=state.metrics.delivered;audio.effect('delivery');}
 if(m.ready&&!state.failed&&!modal.open&&!victoryQueued&&(state.scenario!=='coast'||state.chapter===3)){victoryQueued=true;setTimeout(()=>{if(S.mission(state).ready)showReward();victoryQueued=false;},0);}
 if(state.failed&&!failedShown){failedShown=true;setTimeout(()=>{setRunning(false);openPanel('failure');audio.unlock().then(()=>audio.effect('late'));save(false);},0);}
}
function showInspector(type){inspector=type;$('inspector').hidden=!type;$('workspace').classList.toggle('has-inspector',!!type);document.querySelectorAll('[data-info]').forEach(el=>el.hidden=el.dataset.info!==type);document.querySelectorAll('[data-inspector]').forEach(el=>el.setAttribute('aria-expanded',String(el.dataset.inspector===type)));}
function selectBuilding(id){selected=id;world.selected=id;showInspector(id?'facility':null);if(id)renderBuilding();}
function renderBuilding(){const b=state.buildings.find(b=>b.id===selected);if(!b){selected=null;$('context-panel').hidden=true;return;}const meta=S.TYPES[b.type],st=S.status(state,b),j=state.jobs.find(j=>j.id===b.active),remaining=j&&j.status==='work'?(S.PRODUCTS[j.product].work[j.stage]-b.progress)/(S.speed(state,b)||1):0;
 $('context-panel').innerHTML=`<header><div><span class="eyebrow">FACILITY ${esc(b.id.slice(1).padStart(2,'0'))}</span><h2>${meta.name}</h2><span class="chip ${['broken','blocked'].includes(st.kind)?'bad':''}">${st.label}</span></div><button class="close" data-action="deselect" aria-label="設備パネルを閉じる">×</button></header>
 <p>${meta.desc}</p>
 ${b.type==='warehouse'?`<div class="label">保管中 / 保管容量</div><div class="big-value">${b.queue.length} / ${6*b.level} <small>両</small></div><p>空きができた後工程へ自動出庫。保管料は1両につき0.25G / 秒。工程前の待ち場所（0.60G / 秒）より安く保管できます。</p>`:`<div class="meter"><span>配置人員</span><b>${b.staff} / 4 人</b></div><div class="row-actions"><button class="secondary" data-action="assign" data-id="${b.id}" data-delta="-1" ${b.staff===0?'disabled':''}>− 1人</button><button class="primary" data-action="assign" data-id="${b.id}" data-delta="1" ${b.staff===4||S.freeStaff(state)===0?'disabled':''}>＋ 1人</button><span class="tiny">未配置 ${S.freeStaff(state)}人</span></div>`}
 ${meta.stage!==null?`<div class="meter"><span>設備の状態</span><b class="${b.condition<30?'danger':''}">${Math.ceil(b.condition)}%</b></div><div class="track"><i style="width:${b.condition}%;background:${b.condition<30?'#c45d42':'#358d71'}"></i></div>
 <div class="kv-grid"><div>順番待ち<b>${b.queue.length+S.incoming(state,b.id)} <small>両</small></b></div><div>作業能力<b>${S.speed(state,b).toFixed(2)} <small>倍</small></b></div><div>完了<b>${b.completed} <small>両</small></b></div></div>
 ${j?`<div class="list-card"><div class="flex">${train(j.product)}<div><b>${S.PRODUCTS[j.product].name}</b><div class="tiny">${j.status==='blocked'?'後工程か倉庫の空きを待っています':b.broken?'故障停止中':b.repairRemaining?'保全終了まで あと'+Math.ceil(b.repairRemaining)+'秒':b.staff===0?'人員を配置してください':'作業完了まで あと'+Math.max(0,Math.ceil(remaining))+'秒'}</div><div class="tiny">${deadline(j.deadline-state.t)}</div></div></div></div>`:''}
 <div class="row-actions">${b.broken?`<button class="primary full" data-action="repair" data-id="${b.id}" ${b.repairRemaining||state.cash<800?'disabled':''}>${b.repairRemaining?'修理中 · あと'+Math.ceil(b.repairRemaining)+'秒':'故障修理 · 800 G / 16秒'}</button>`:`<button class="secondary full" data-action="preventive" data-id="${b.id}" ${b.repairRemaining||b.condition>=99||state.cash<300?'disabled':''}>${b.repairRemaining?'予防保全中 · あと'+Math.ceil(b.repairRemaining)+'秒':'予防保全 · 300 G / 8秒'}</button>`}</div>`:''}
 ${b.type!=='maintenance'?`<div class="meter"><span>設備レベル</span><b>Lv. ${b.level} / 3</b></div><button class="primary full" data-action="upgrade" data-id="${b.id}" ${b.level>=3||state.cash<S.upgradeCost(b)?'disabled':''}>${b.level>=3?'最大レベル':(b.type==='warehouse'?'容量を6両増設':'能力を30%分追加')+' · '+money(S.upgradeCost(b))+' G'}</button>`:''}
 <p class="tiny">維持費 ${meta.upkeep*b.level} G / 秒${meta.stage!==null?' · 搬入口 X'+(b.x+1)+' Y'+(b.y+3):''}</p><button class="text-button danger" data-action="demolish" data-id="${b.id}">設備を撤去する</button>`;
}
function routeSelect(stage,order=null){
 const bs=state.buildings.filter(b=>S.TYPES[b.type].stage===stage),names=['設計','加工','組立','検査'];
 const chosen=order?.routes?.[stage]||(!order?state.routeDefaults?.[stage]:'')||'';
 const inherited=state.routeDefaults?.[stage];
 if(bs.length<2)return `<label>${names[stage]}<span class="chip">${bs[0]?S.TYPES[bs[0].type].short+' '+bs[0].id.slice(1):'設備なし'}</span></label>`;
 return `<label>${names[stage]}<select data-route-stage="${stage}" data-order="${order?.id||''}" aria-label="${order?order.id+'の':'標準の'}${names[stage]}経路"><option value="">${order?'標準設定に従う'+(inherited?'（設備 '+inherited.slice(1)+'）':'（自動）'):'自動：負荷と運搬距離'}</option>${bs.map(b=>`<option value="${b.id}" ${chosen===b.id?'selected':''}>${names[stage]} ${b.id.slice(1)} · ${b.staff}人 · ${S.status(state,b).label}</option>`).join('')}</select></label>`;
}
function flowPanel(){const q=S.summary(state),bs=state.buildings.filter(b=>S.TYPES[b.type].stage!==null),orders=state.orders.filter(o=>o.status==='active');return `
 <p class="intro">現在の人員・経路で、受注済みの車両をいつつくれるか予測します。設定を変更するとガントチャートを再計算します。</p>
 <div class="resource-grid">${bs.map(b=>`<div class="resource-card"><strong>${S.TYPES[b.type].short} ${b.id.slice(1)} · ${b.staff}人</strong><span>${S.status(state,b).label} · 能力 ${S.speed(state,b).toFixed(2)}倍</span><div class="row-actions"><button class="secondary" data-action="assign" data-id="${b.id}" data-delta="-1" aria-label="${b.id}の人員を1人戻す" ${b.staff===0?'disabled':''}>−</button><button class="text-button" data-focus="${b.id}">設備へ</button><button class="primary" data-action="assign" data-id="${b.id}" data-delta="1" aria-label="${b.id}へ1人配置" ${b.staff>=4||S.freeStaff(state)===0?'disabled':''}>＋</button></div>${b.broken?`<button class="secondary full" data-action="repair" data-id="${b.id}" ${b.repairRemaining||state.cash<800?'disabled':''}>修理 · 800G / 16秒</button>`:''}</div>`).join('')}</div>
 <p class="tiny">未配置 ${q.freeStaff}人 · 給与合計 ${(state.employees*.48).toFixed(2)}G / 秒 <button class="text-button" data-panel="staff">採用・減員へ</button></p>
 <h3>これからの生産計画</h3><div id="gantt-result" role="status">設備の空きと運搬を計算しています…</div>
 <details class="route-order" data-key="defaults"><summary>標準の経路・投入設定</summary><div class="route-controls">${[0,1,2,3].map(i=>routeSelect(i)).join('')}</div><label class="control"><span>自動着工</span><input type="checkbox" class="toggle" data-setting="release" ${state.releaseEnabled?'checked':''}></label><label class="control"><span>製造中の上限（完成品は除く）</span><select data-setting="wip">${[2,3,4,5,6,8,10,12].map(n=>`<option value="${n}" ${state.wipLimit===n?'selected':''}>${n}両</option>`).join('')}</select></label><label class="control"><span>着工・作業の優先順位</span><select data-setting="priority"><option value="edd" ${state.priority==='edd'?'selected':''}>納期が近い順</option><option value="fifo" ${state.priority==='fifo'?'selected':''}>到着した順</option></select></label></details>
 <h3>受注ごとの経路</h3><p class="tiny">指定した設備が空くまで待ちます。運搬中・作業中の車両はその工程を続け、次の運搬から変更が効きます。</p>
 ${orders.map(o=>`<details class="route-order" data-key="${o.id}"><summary>${o.id.toUpperCase()} · ${S.PRODUCTS[o.product].name} × ${o.quantity}両</summary>${deadline(o.deadline-state.t)}<label class="control"><span>未着工分の着工予約</span><select data-release-order="${o.id}" aria-label="${o.id}の着工予約"><option value="${Math.max(0,Math.round((o.releaseAt||state.t)-state.t))}">${o.releaseAt>state.t?"今から "+Math.ceil(o.releaseAt-state.t)+"秒後":"今すぐ（空き待ち）"}</option>${[0,15,30,60,90,120,180].map(n=>`<option value="${n}">今から ${n}秒後</option>`).join('')}</select></label><div class="route-controls">${[0,1,2,3].map(i=>routeSelect(i,o)).join('')}</div><p class="tiny">出荷 ${o.shipped} / ${o.quantity} · 未着工 ${o.quantity-o.released}両</p></details>`).join('')||'<p>現在の受注はすべて出荷済みです。</p>'}
 <details class="route-order" data-key="storage"><summary>仕掛・倉庫を管理する</summary><p>製造中 ${q.wip}両 · 中間倉庫 ${q.warehouseStock}/${q.warehouseCapacity}両 · 完成品 ${q.finishedStock}両</p><p class="tiny">工程前の待ち場所 0.60G、中間倉庫 0.25G、完成品倉庫 0.90G / 両・ゲーム秒。完成品は納期になると出荷し、売上が入ります。</p>${state.jobs.map(j=>`<div class="list-card"><b>${j.id.toUpperCase()} · ${S.PRODUCTS[j.product].name}</b>${deadline(j.deadline-state.t)}<span class="chip">${{work:'作業中',queue:'工程前で待機',blocked:'工程完了・後工程待ち',buffer:j.held?'手動退避中':'中間倉庫',transfer:'運搬中',finished:'完成品倉庫'}[j.status]}</span>${j.held?`<button class="secondary" data-action="resumeJob" data-id="${j.id}">出庫を再開</button>`:['queue','blocked'].includes(j.status)&&j.stage<4?`<button class="secondary" data-action="park" data-id="${j.id}" ${q.warehouseCapacity<=q.warehouseStock?'disabled':''}>中間倉庫に退避</button>`:''}</div>`).join('')}</details>`;}
function requestPlan(){const token=++planGeneration,target=$('gantt-result');if(!target)return;target.textContent='設備の空きと運搬を計算しています…';const iterator=YardPlanner.calculate(state);
 function chunk(){if(token!==planGeneration||modalPanel!=='flow')return;try{const result=iterator.next();if(result.done){target.innerHTML=chart(result.value);return;}setTimeout(chunk,0);}catch(error){target.textContent='計画を計算できませんでした。工場へ戻り、もう一度開いてください。';}}
 setTimeout(chunk,0);
}
function chart(plan){const stageColors=['#2589ab','#b77d20','#168363','#7958a8'],names=['設計','加工','組立','検査'];if(!plan.rows.length)return '<p>未出荷の受注はありません。</p>';
 const span=Math.max(60,Math.ceil(Math.max(...plan.rows.map(r=>Math.max(r.deadline,r.finish||r.lastSeen||0)))/60)*60);
 const position=n=>Math.max(0,Math.min(100,n/span*100));
 const bars=row=>row.spans.map(b=>{const working=b.kind==='work',color=working?stageColors[b.stage]||'#168363':b.kind==='finished'?'#d17c29':b.kind==='buffer'?'#8c9349':b.kind==='stopped'?'#b3433f':b.kind==='transfer'?'#607f92':'#a6b7b0';const label=working?names[b.stage]+' '+String(b.facility).slice(1):{finished:'完成品保管',buffer:'中間倉庫',stopped:'故障・保全・人員待ち',transfer:'運搬',queue:'順番待ち',blocked:'後工程待ち'}[b.kind]||'待ち';return `<span class="gantt-bar ${working?'':'wait'}" style="left:${position(b.start)}%;width:${Math.max(.15,(b.end-b.start)/span*100)}%;background:${color}" role="img" aria-label="${esc(label)} 今から${Math.round(b.start)}〜${Math.round(b.end)}秒" title="${esc(label)}：今から${Math.round(b.start)}〜${Math.round(b.end)}秒">${working?esc(label):''}</span>`;}).join('');
 return `<div class="stage-legend">${names.map((n,i)=>`<span><i style="background:${stageColors[i]}"></i>${n}</span>`).join('')}<span><i style="background:#607f92"></i>運搬・待ち</span><span><i style="background:#d17c29"></i>完成品保管</span><span>赤い破線：納期</span></div><p class="tiny">横にスクロールして先の工程を確認できます。時刻はすべて「今から何秒後」です。</p><div class="schedule-scroll"><div class="schedule-chart" style="width:${Math.max(720,Math.min(1800,span*2.2))}px"><div class="schedule-axis"><div class="schedule-name">受注 / 車両</div><div class="schedule-track">${Array.from({length:10},(_,i)=>`<span class="time-tick" style="left:${i*10}%">${Math.round(span*i/10)}秒後</span>`).join('')}</div></div>${plan.rows.map(r=>`<div class="schedule-row"><div class="schedule-name">${esc(r.order.toUpperCase())} / ${esc(r.id.toUpperCase())}<small>${esc(S.PRODUCTS[r.product].name)}</small></div><div class="schedule-track">${bars(r)}<i class="due-line" style="left:${position(r.deadline)}%"></i><span class="due-label" style="left:${position(r.deadline)}%">納期</span></div></div>`).join('')}</div></div><div class="schedule-result">${plan.rows.filter(r=>r.shipped&&!r.late).length}両は納期内の見込み · <span class="status-late">${plan.rows.filter(r=>r.late).length}両は遅延見込み</span> · ${plan.rows.filter(r=>!r.shipped).length}両は完了未確定</div>${plan.rows.filter(r=>!r.shipped||r.late).map(r=>`<div class="schedule-warning">${esc(r.order.toUpperCase())} / ${esc(r.id.toUpperCase())}：${r.warning||'納期を約'+Math.max(1,Math.round(r.ready-r.deadline))+'秒超過する見込み'}</div>`).join('')}<details class="route-order" data-key="assumptions"><summary>予測に含める条件</summary><p class="tiny">${esc(plan.assumptions)}</p></details>`;
}
function ceremony(win){return `<div class="ceremony ${win?'win':'loss'}" role="status">${Array.from({length:20},(_,i)=>`<i class="confetti" aria-hidden="true" style="--x:${i*5}%;--d:${-(i%7)*.31}s;--c:${['#ffc766','#6ee6c3','#f5fff1'][i%3]}"></i>`).join('')}<h3>${win?'PERFECT<br>SCHEDULE':'GAME OVER'}</h3><p>${win?'シナリオクリア！<br>あなたの判断が、工場を動かしました。':'運転資金が尽きました。<br>この工場での経験を、次の挑戦へ。'}</p>${win?'<span class="ceremony-train" aria-hidden="true"></span>':''}</div>`;}

const titles={build:'工場をひろげる',staff:'人が、工場を動かす。',orders:'次の一両を、引き受ける。',flow:'流れを整える',finance:'工場の経営帳簿',settings:'設定と保存',scenarios:'次の工場へ',help:'工場長の手引き',events:'工場の出来事',reward:'流れが、ひとつ進んだ。',failure:'工場を立て直そう'};
function openPanel(type){if(!modal.open){resumeAfter=running;setRunning(false);}document.body.classList.add('manage-open');modal.dataset.panel=type;modalPanel=type;drawPanel();if(!modal.open)modal.showModal();render(true);}
function closeModal(resume=true){modal.close();document.body.classList.remove('manage-open');modalPanel=null;planGeneration++;document.querySelectorAll('[data-panel]').forEach(x=>x.classList.remove('active'));if(resume&&resumeAfter)setRunning(true);resumeAfter=false;render(true);}
function drawPanel(){const previousScroll=$('modal-body').scrollTop,openDetails=[...$('modal-body').querySelectorAll('details[open][data-key]')].map(x=>x.dataset.key);const type=modalPanel;$('modal-title').textContent=titles[type]||titles.help;$('modal-eyebrow').textContent='操業を一時停止中 · ×で工場へ戻る';let html='';
 if(type==='build')html=`<p class="intro">建物を選び、マップをタップして配置。操業は一時停止します。生産設備には建設後に人を配置してください。</p><div class="card-grid">${Object.entries(S.TYPES).map(([id,t])=>`<button class="build-card" data-build="${id}" ${state.cash<t.cost?'disabled':''}>${preview(id)}<strong>${t.name}</strong><span class="price">${money(t.cost)} G</span><small>${t.desc}<br>維持費 ${t.upkeep} G / 秒</small><span class="primary">配置場所を選ぶ</span></button>`).join('')}</div><div class="list-card flex"><div><h3>用地を拡張</h3><p class="intro" style="margin:0">東・北の区画を開放。遠い工場は運搬時間も増えます。</p></div><button class="primary" data-action="expand" ${state.expanded||state.cash<6000?'disabled':''}>${state.expanded?'拡張済み':'6,000 G'}</button></div>`;
 if(type==='staff')html=`<p class="intro">採用時に1人350G、採用後は1人につき0.48 G / ゲーム秒の給与が発生します。未配置でも給与は必要です。人を増やす前に、詰まる工程へ配置し直してみましょう。</p><div class="kv-grid"><div>全従業員<b>${state.employees} <small>人</small></b></div><div>配置済み<b>${state.employees-S.freeStaff(state)} <small>人</small></b></div><div>未配置<b>${S.freeStaff(state)} <small>人</small></b></div></div><div class="row-actions"><button class="primary" data-action="hire" ${state.cash<350||state.employees>=60?'disabled':''}>1人採用 · 350 G</button><button class="secondary" data-action="dismiss" ${S.freeStaff(state)<1||state.cash<200?'disabled':''}>未配置の1人を減員 · 200 G</button></div><table class="info-table"><thead><tr><th>設備</th><th>状態</th><th>配置</th></tr></thead><tbody>${state.buildings.filter(b=>b.type!=='warehouse').map(b=>`<tr><td><button data-focus="${b.id}">${S.TYPES[b.type].short} ${b.id.slice(1).padStart(2,'0')} ↗</button></td><td>${S.status(state,b).label}</td><td><button data-action="assign" data-id="${b.id}" data-delta="-1" aria-label="${S.TYPES[b.type].short}から1人戻す" ${!b.staff?'disabled':''}>−</button> ${b.staff} <button data-action="assign" data-id="${b.id}" data-delta="1" aria-label="${S.TYPES[b.type].short}へ1人配置" ${b.staff>=4||S.freeStaff(state)<1?'disabled':''}>＋</button></td></tr>`).join('')}</tbody></table><div class="expense-note">現在の給与：${state.employees}人 × 0.48 = <b>${(state.employees*.48).toFixed(2)} G / 秒</b>。1人採用すると ${( (state.employees+1)*.48).toFixed(2)} G / 秒になります。</div><div class="note">2人が標準能力。3人で1.33倍、4人で1.66倍。制約以外に増員しても、工場全体の出荷が増えるとは限りません。</div>`;
 if(type==='orders'){const active=state.orders.filter(o=>o.status==='active');html=`<p class="intro">${running?'':'商談中は一時停止。'}受注時の支払いはありません。材料費は1両ずつ着工時に必要です。納期はゲーム内の残り秒数です。</p><h3>商談 ${state.offers.length}件</h3>${state.offers.length?state.offers.map(o=>{const p=S.PRODUCTS[o.product];return `<div class="list-card"><div class="order-top">${train(o.product)}<div><h3>${p.name} × ${o.quantity}両</h3><p>${deadline(o.deadline-state.t)} · 受付はあと${Math.max(0,Math.ceil(o.expires-state.t))}秒</p></div></div><div class="kv-grid"><div>売上見込<b>${money(o.unitSale*o.quantity)} <small>G</small></b></div><div>必要材料費<b>${money(p.cost*o.quantity)} <small>G</small></b></div><div>材料差引利益<b>${money((o.unitSale-p.cost)*o.quantity)} <small>G</small></b></div></div><p class="tiny">標準作業 ${p.work.map((n,i)=>['設計','加工','組立','検査'][i]+Math.round(n)+'秒').join(' / ')}<br>標準2人・設備Lv.1。運搬・待ち・故障を含みません。給与等は上の利益から別途差し引かれます。</p><div class="row-actions"><button class="primary" data-action="accept" data-id="${o.id}" ${active.length>=10?'disabled':''}>受注する</button><button class="secondary" data-action="reject" data-id="${o.id}">見送る</button></div></div>`;}).join(''):'<p class="muted">現在商談はありません。操業を進めると次の注文が届きます。</p>'}<h3>受注済み ${active.length}件</h3>${active.map(o=>`<div class="list-card"><div class="flex"><div><b>${S.PRODUCTS[o.product].name} × ${o.quantity}両</b><p class="tiny">${deadline(o.deadline-state.t)}</p></div><span class="chip">出荷 ${o.shipped} / ${o.quantity}</span></div><p class="tiny">着工済み ${o.released}両 · 未着工 ${o.quantity-o.released}両</p></div>`).join('')||'<p class="muted">新しい商談を受注しましょう。</p>'}`;}
 if(type==='flow')html=flowPanel();
 if(type==='finance'){const l=state.ledger,q=S.summary(state);html=`<p class="intro">お金の単位はゲーム内通貨G。営業利益と運転資金は別に見ます。設備投資や未完成品の材料購入は、現金を先に減らします。</p><div class="kv-grid"><div>運転資金<b>${money(state.cash)} <small>G</small></b></div><div>累計営業利益<b>${money(q.profit)} <small>G</small></b></div><div>納期内出荷<b>${Math.round(q.ontime*100)} <small>%</small></b></div></div><table class="info-table"><tbody>${[['出荷売上',l.revenue],['出荷済み車両の材料費',-l.cogs],['給与',-l.wages],['設備維持費',-l.upkeep],['工程前の待ち場所',-l.storageFloor],['中間倉庫の保管料',-l.storageIntermediate],['完成品倉庫の保管料',-l.storageFinished],['納期遅延の控除',-l.penalties],['採用・退職支援・保全費',-l.service],['累計営業利益',q.profit]].map(([a,n])=>`<tr><td>${a}</td><td>${n<0?'−':''}${money(Math.abs(n))} G</td></tr>`).join('')}</tbody></table><h3>資金の使い道</h3><table class="info-table"><tbody><tr><td>累計設備・用地投資（撤去回収控除後）</td><td>${money(l.capex)} G</td></tr><tr><td>在庫（仕掛・完成品）の材料原価</td><td>${money(l.materials-l.cogs)} G</td></tr><tr><td>目標達成の助成金</td><td>${money(l.rewards)} G</td></tr><tr><td>固定支出（給与＋設備維持費）</td><td>${(state.employees*.48+state.buildings.reduce((n,b)=>n+S.TYPES[b.type].upkeep*b.level,0)).toFixed(2)} G / 秒</td></tr><tr><td>着工から出荷までの平均</td><td>${Math.round(q.averageCycle)}秒</td></tr></tbody></table><div class="note">簡易管理会計です。助成金と設備投資は営業利益に含めず、減価償却・税金・借入は試作版では省略。資金が0Gに達するとゲームオーバーです。完成品は納期まで保管し、出荷時に売上が入ります。</div>`;}
 if(type==='settings')html=`<p class="intro">工場はこのブラウザに保存されます。端末間の同期はありません。別のタブやアプリへ移ると自動で一時停止します。</p><label class="control"><span>BGM</span><input type="checkbox" class="toggle" data-setting="music" ${prefs.music?'checked':''}></label><label class="control"><span>効果音</span><input type="checkbox" class="toggle" data-setting="fx" ${prefs.fx?'checked':''}></label><label class="control"><span>作業アニメーション</span><input type="checkbox" class="toggle" data-setting="motion" ${prefs.motion?'checked':''}></label><div class="row-actions"><button class="primary" data-action="save">今すぐ保存</button><button class="secondary" data-action="sound">音を試す</button><button class="secondary" data-panel="help">遊び方</button></div><div class="list-card"><h3>最初からやり直す</h3><p class="muted">現在の工場を終了し、新しいシナリオを選びます。選択時にもう一度確認します。</p><button class="secondary" data-panel="scenarios">シナリオ選択へ</button></div><p class="device-note">PC：ドラッグ・ホイール。スマートフォン：1本指で移動、2本指で拡大縮小。設備一覧からも選択できます。</p><a class="text-button" href="proposal.html" target="_blank" rel="noopener">企画書を開く ↗</a>`;
 if(type==='scenarios')html=`<p class="intro">3つのシナリオと自由経営。新しい工場を始めると、現在の途中保存が置き換わります。</p><div class="card-grid">${Object.entries(S.SCENARIOS).map(([id,m],i)=>`<button class="build-card scenario-card" data-scenario="${id}"><span class="eyebrow">0${i+1} / ${esc(m.sub)}</span><strong>${m.name}</strong><small>${m.desc}</small><span class="price">初期資金 ${money(m.cash)} G</span><span class="primary">この工場を選ぶ</span></button>`).join('')}</div>`;
 if(type==='help')html=`<p class="intro">${S.mission(state).hint}</p><div class="hint-list"><div><b><span class="num">1</span>流れを眺める</b><p>操業を開始すると受注済みの3両を製造。設計→加工→組立→検査を経て、出荷すると売上が入ります。マップをドラッグして工場内を探索できます。</p></div><div><b><span class="num">2</span>詰まりを見つける</b><p>待ちの数字と設備の状態を確認。詰まる工程に未配置の2人を応援に回してみましょう。必要なら採用・改良・工場増設へ。</p></div><div><b><span class="num">3</span>倉庫と投入を使う</b><p>倉庫を建てると中間品を退避できます。製造中の上限を下げて、つくりすぎも防げます。増設した設備には人を配置してください。</p></div><div><b><span class="num">4</span>利益を育てる</b><p>新しい注文を受け、出荷を重ねて目標を達成。資金を残しながら再投資し、故障には修理・予防保全で対応します。</p></div></div><div class="note">時間はゲーム内の秒。1×なら現実の1秒で1秒進みます。1日表示は120秒で進みます。商談・雇用などの画面では時間が止まるため、落ち着いて判断できます。</div><div class="row-actions"><button class="primary" data-action="close">工場へ戻る</button></div>`;
 if(type==='events')html=state.news.map(n=>`<div class="list-card"><div class="tiny">DAY ${Math.floor(n.t/120)+1} · 開始から${Math.floor(n.t)}秒</div><h3>${esc(n.title)}</h3><p class="muted">${esc(n.body)}</p>${n.buildingId?`<button class="text-button" data-focus="${esc(n.buildingId)}">設備の場所へ →</button>`:''}</div>`).join('');
 if(type==='failure')html=ceremony(false)+`<div class="success-banner" style="background:#854f38"><h3>運転資金が不足しました</h3><p>出荷した車両は${state.metrics.delivered}両。材料の先払い・給与・投資が重なると、利益が出る見込みでも資金が先に尽きます。</p></div><p class="intro">次は受注を絞り、出荷してから再投資してみましょう。未配置の人も給与が掛かるため、配置と雇用を一緒に見直せます。</p><div class="row-actions"><button class="primary" data-panel="scenarios">新しい工場で再挑戦</button><button class="secondary" data-panel="finance">帳簿で振り返る</button></div>`;
 $('modal-body').innerHTML=html;for(const d of $('modal-body').querySelectorAll('details[data-key]'))d.open=openDetails.includes(d.dataset.key);$('modal-body').scrollTop=previousScroll;if(type==='flow')requestPlan();
}
function startBuild(type){buildResume=resumeAfter;closeModal(false);selectBuilding(null);world.placement={type,pos:{x:18,y:7}};pendingPlace=null;$('build-hint').hidden=false;renderBuildHint();render(true);}
function renderBuildHint(){const t=S.TYPES[world.placement.type],p=pendingPlace,c=p?S.buildCheck(state,world.placement.type,p.x,p.y):null;$('build-hint').innerHTML=`<strong>${t.name} · ${money(t.cost)} G</strong><p>${p?`X ${p.x} · Y ${p.y} — ${c.message}`:'マップを移動して、空いた区画をタップしてください。'}</p><div class="row-actions"><button class="primary" data-action="confirmBuild" ${!c?.ok?'disabled':''}>ここに建設</button><button class="secondary" data-action="cancelBuild">キャンセル</button></div>`;}
function placeAt(pos){pendingPlace=pos;renderBuildHint();}
function finishBuild(){world.placement=null;pendingPlace=null;$('build-hint').hidden=true;if(buildResume)setRunning(true);buildResume=false;render(true);}
function newGame(id){state=S.create(id);selected=null;world.selected=null;world.placement=null;loaded=false;lastDelivery=0;lastAutosave=0;failedShown=false;running=false;accumulator=0;rate=1;resumeAfter=false;audio.reset();audio.setStage(S.SCENARIOS[id].seed);closeModal(false);showInspector(null);world.fitOnResize=true;world.home();$('context-panel').hidden=true;save(false);render(true);toast('新しい工場へようこそ。操業開始を押してください。');}
function confirmScenario(id){$('modal-title').textContent='新しい工場を始めますか？';$('modal-body').innerHTML=`<p>${S.SCENARIOS[id].name}を始めます。現在の工場の途中保存は置き換わります。</p><div class="row-actions"><button class="primary" data-newgame="${id}">新しい工場を始める</button><button class="secondary" data-panel="scenarios">戻る</button></div>`;}
function showReward(){const m=S.mission(state);if(!m.ready){openPanel(m.complete?'scenarios':'help');return;}openPanel('reward');const r=S.claim(state);if(!r.ok){toast(r.message,true);closeModal();return;}audio.unlock().then(()=>audio.effect('win'));save(false);$('modal-body').innerHTML=(r.complete?ceremony(true):'')+`<div class="success-banner"><h3>${esc(r.message)}</h3><p>${esc(r.lesson)}</p></div><p class="intro">${r.complete?'シナリオクリア！ この工場を続けて発展させることも、別のシナリオへ進むこともできます。':S.mission(state).hint}</p><div class="row-actions"><button class="primary" data-action="close">工場を続ける</button>${r.complete?'<button class="secondary" data-panel="scenarios">次のシナリオへ</button>':''}</div>`;render(true);}
function act(action,id,value){
 if(action==='close'){closeModal();return;}if(action==='replan'){requestPlan();return;}if(action==='deselect'){selectBuilding(null);return;}
 if(action==='save'){save();return;}if(action==='sound'){audio.unlock().then(()=>{audio.effect('great');toast('効果音を試聴しました。');});return;}
 if(action==='cancelBuild'){finishBuild();return;}if(action==='confirmBuild'){if(!world.placement||!pendingPlace)return;const r=S.build(state,world.placement.type,pendingPlace.x,pendingPlace.y);if(result(r)){finishBuild();selectBuilding(r.id);}return;}
 if(action==='demolish'){
  openPanel('build');$('modal-title').textContent='設備を撤去しますか？';$('modal-body').innerHTML=`<p>設備投資額の35%を回収します。配置人員は未配置に戻ります。最後の1棟、作業中・待ち・運搬中・保全中の設備は撤去できません。</p><div class="row-actions"><button class="primary" data-action="confirmDemolish" data-id="${esc(id)}">この設備を撤去</button><button class="secondary" data-action="close">キャンセル</button></div>`;return;}
 if(action==='confirmDemolish'){if(result(S.demolish(state,id))){selectBuilding(null);closeModal();}return;}
 const calls={park:()=>S.park(state,id),resumeJob:()=>S.resumeJob(state,id),accept:()=>S.accept(state,id),reject:()=>S.reject(state,id),hire:()=>S.hire(state),dismiss:()=>S.dismiss(state),assign:()=>S.assign(state,id,+value),repair:()=>S.repair(state,id),preventive:()=>S.repair(state,id,true),upgrade:()=>S.upgrade(state,id),expand:()=>S.expand(state)};
 if(calls[action]){result(calls[action]());if(modal.open)drawPanel();}
}
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.dataset.inspector){showInspector(inspector===el.dataset.inspector?null:el.dataset.inspector);return;}if(el.dataset.panel){openPanel(el.dataset.panel);return;}if(el.dataset.build){startBuild(el.dataset.build);return;}if(el.dataset.action){act(el.dataset.action,el.dataset.id,el.dataset.delta);return;}if(el.dataset.select){world.focus(el.dataset.select);selectBuilding(el.dataset.select);return;}if(el.dataset.focus){const id=el.dataset.focus;closeModal();world.focus(id);selectBuilding(id);return;}if(el.dataset.scenario){confirmScenario(el.dataset.scenario);return;}if(el.dataset.newgame){newGame(el.dataset.newgame);return;}if(el.dataset.speed){rate=+el.dataset.speed;render(true);}});
document.addEventListener('change',e=>{const el=e.target,k=el.dataset.setting;if(el.dataset.releaseOrder){result(S.setRelease(state,el.dataset.releaseOrder,+el.value));drawPanel();return;}if(el.dataset.routeStage!==undefined){result(S.setRoute(state,el.dataset.order||null,+el.dataset.routeStage,el.value||null));drawPanel();return;}if(!k)return;if(k==='release')state.releaseEnabled=el.checked;if(k==='wip')state.wipLimit=+el.value;if(k==='priority')state.priority=el.value;if(k==='music'){prefs.music=el.checked;audio.setChannel('music',el.checked);}if(k==='fx'){prefs.fx=el.checked;audio.setChannel('fx',el.checked);}if(k==='motion'){prefs.motion=el.checked;document.body.classList.toggle('motion-off',!el.checked);world.reduced=!el.checked||matchMedia('(prefers-reduced-motion: reduce)').matches;}save(false);drawPanel();render(true);});
document.addEventListener('pointerdown',e=>{if(e.target.closest('.context'))holdUI=true;});document.addEventListener('pointerup',()=>setTimeout(()=>holdUI=false,100));document.addEventListener('pointercancel',()=>holdUI=false);
document.addEventListener('visibilitychange',()=>{if(document.hidden){setRunning(false);resumeAfter=false;buildResume=false;save(false);}last=performance.now();});window.addEventListener('pagehide',()=>{setRunning(false);save(false);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&inspector&&!modal.open){selectBuilding(null);e.preventDefault();}if(e.key==='Escape'&&world.placement){finishBuild();e.preventDefault();}if(e.code==='Space'&&!modal.open&&!world.placement&&!/INPUT|SELECT|BUTTON/.test(e.target.tagName)){e.preventDefault();loaded=true;setRunning(!running);}});
modal.addEventListener('cancel',e=>{e.preventDefault();closeModal();});modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
$('fold-info').onclick=()=>showInspector(null);$('close-modal').onclick=()=>closeModal();$('play').onclick=()=>{loaded=true;setRunning(!running);};$('settings').onclick=()=>openPanel('settings');$('scenarios').onclick=()=>openPanel('scenarios');$('mission-action').onclick=showReward;$('zoom-in').onclick=()=>{world.zoom(1.2);render(true);};$('zoom-out').onclick=()=>{world.zoom(1/1.2);render(true);};$('recenter').onclick=()=>{world.home();render(true);};$('heatmap').onclick=()=>{world.heat=!world.heat;$('heatmap').classList.toggle('active',world.heat);toast(world.heat?'混雑表示：赤は故障、橙は待ち、緑は余裕。':'通常の工場表示に戻しました。');};
function frame(t){const dt=Math.min(.3,(t-last)/1000);last=t;if(running){accumulator+=dt*rate;while(accumulator>=S.STEP){S.step(state);accumulator-=S.STEP;if(state.failed){setRunning(false);break;}}if(state.t-lastAutosave>=15){lastAutosave=state.t;save(false);}}
 world.draw(t,running);if(t-lastUI>350){render();lastUI=t;}requestAnimationFrame(frame);}
document.body.classList.toggle('motion-off',!prefs.motion);render(true);requestAnimationFrame(frame);if(loaded)toast('保存した工場を読み込みました。「再開」で操業できます。');
})();
